@SpringBootTest(properties={"testhub.registration.enabled=true","testhub.bootstrap.demo-enabled=false"})
@AutoConfigureMockMvc @ActiveProfiles(resolver=FunctionalDatabaseProfile.class) @DirtiesContext
class FunctionalHistorySyncFlowTests {
    @TempDir static Path directory;
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r) {
        if(FunctionalDatabaseProfile.mysql()) FunctionalDatabaseProfile.configure(r,directory,"history-sync-fixture");
        else {r.add("testhub.desktop.data-directory",directory::toString);r.add("spring.datasource.url",()->"jdbc:h2:file:"+directory.resolve("workspace")+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_ON_EXIT=FALSE");r.add("spring.datasource.username",()->"sa");r.add("spring.datasource.password",()->"history-sync-fixture");}
    }
    @Autowired RegistrationService registration; @Autowired AccessService access;
    @Autowired FunctionalHistorySyncService sync; @Autowired FunctionalAssetService assets;
    @Autowired FunctionalDefectService defects; @Autowired FunctionalTestExecutionService executions;
    @Autowired FunctionalTransferService transfer; @Autowired ObjectMapper json; @Autowired JdbcClient jdbc; @Autowired MockMvc mvc;
    @Autowired org.springframework.transaction.PlatformTransactionManager transactionManager;
    @MockitoSpyBean AuditService audit;
    record Fixture(PlatformUserPrincipal actor,String project,FunctionalRequirement requirement,FunctionalCase testcase,FunctionalTestPlan plan,FunctionalDefect defect) { }
    Fixture fixture() {
        var name="execution-sync-"+UUID.randomUUID();var actor=new PlatformUserPrincipal(registration.register(name,name+"@example.test","执行关联验收","Sync-fixture-2026!"));var c=access.context(actor);var p=c.projects().get(c.organizations().getFirst().id()).getFirst().id();
        var rf=assets.createCatalog(actor,p,new FunctionalAssetService.CatalogInput("需求",null,0,"REQUIREMENTS"));var cf=assets.createCatalog(actor,p,new FunctionalAssetService.CatalogInput("用例",null,0,"CASES"));
        var req=assets.createRequirement(actor,p,new FunctionalAssetService.RequirementInput(rf.id(),"REQ-1","需求","P1","APPROVED","原正文"));
        var tc=assets.createCase(actor,p,new FunctionalAssetService.CaseInput(cf.id(),req.id(),"CASE-1","用例","P1","READY","SECURITY","前置","步骤","结果"));
        var plan=executions.createPlan(actor,p,new FunctionalTestExecutionService.PlanInput(null,"PLAN-1","计划","READY","原说明",List.of(tc.id())));
        var d=defects.create(actor,p,new FunctionalDefectService.DefectInput(null,"BUG-1","原缺陷",null,"OTHER","",List.of(),List.of(),List.of(actor.userId()),"CRITICAL","P0","CLOSED",true,actor.userId(),"FIXED","TESTHUB",null,"重现步骤"));
        return new Fixture(actor,p,req,tc,plan,d);
    }
    FunctionalTestRun run(Fixture f){return executions.createRun(f.actor(),f.project(),f.plan().id(),"同名批次");}
    Snapshot snapshot(Fixture f){return sync.snapshot(f.actor(),f.project(),f.actor().userId());}
    Item value(Fixture f){return snapshot(f).items().getFirst();}
    Item edit(Item i,java.util.function.Consumer<Map<String,Object>> change){var d=json.convertValue(i.definition(),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});change.accept(d);return new Item(i.kind(),i.name(),d);}
    @SuppressWarnings("unchecked") Map<String,Object> result(Map<String,Object> d){return ((List<Map<String,Object>>)d.get("cases")).getFirst();}
    @SuppressWarnings("unchecked") Map<String,Object> step(Map<String,Object> c){return ((List<Map<String,Object>>)c.get("steps")).getFirst();}
    Request request(Fixture f,Item... items){return new Request(UUID.randomUUID().toString(),f.actor().userId(),snapshot(f).revision(),Arrays.stream(items).map(i->new Operation(UUID.randomUUID().toString(),i,java.time.Instant.parse("2026-10-10T10:00:00.120Z"))).toList());}
    Receipt apply(Fixture f,Item... items){return sync.apply(f.actor(),f.project(),request(f,items));}
    String ref(Item i){return "RUN\n"+i.name().toLowerCase(Locale.ROOT);}
    List<Map<String,Object>> rows(Fixture f){return jdbc.sql("SELECT c.* FROM functional_test_run_case c JOIN functional_test_run r ON r.id=c.run_id WHERE r.project_id=:p ORDER BY c.id").param("p",f.project()).query().listOfRows();}
    List<Map<String,Object>> steps(Fixture f){return jdbc.sql("SELECT s.* FROM functional_test_run_step s JOIN functional_test_run_case c ON c.id=s.run_case_id JOIN functional_test_run r ON r.id=c.run_id WHERE r.project_id=:p ORDER BY s.id").param("p",f.project()).query().listOfRows();}
    @Test void snapshotScopesPortableResultsAndPhysicalLayoutWithoutForeignActors() throws Exception {var f=fixture();var r=run(f);var other=fixture();run(other);var s=snapshot(f);assertEquals(1,s.items().size());assertEquals(r.id(),s.items().getFirst().name());assertEquals(r.createdAt(),s.createdAt().get(ref(value(f))));assertEquals(f.plan().id(),s.layouts().get(ref(value(f))).planId());var text=json.writeValueAsString(s);for(var secret:List.of("createdBy","executedBy","updatedBy",other.actor().userId(),other.project()))assertFalse(text.contains(secret));}
    @Test void newCopyPreservesSourceOriginAndTimesWithActualTargetCreatorAndNewIds(){var a=fixture();var b=fixture();var original=run(a);var v=value(a);var receipt=apply(b,v);var copied=executions.listRuns(b.actor(),b.project(),null).getFirst();assertNotEquals(original.id(),copied.id());assertEquals(b.actor().userId(),copied.createdBy());assertEquals(java.time.Instant.parse("2026-10-10T10:00:00.120Z"),copied.createdAt());assertEquals(v,value(b));assertEquals(copied.id(),receipt.results().getFirst().itemId());assertEquals(snapshot(b).layouts().get(ref(v)),receipt.results().getFirst().layout());assertEquals(b.testcase().id(),receipt.results().getFirst().assetIds().get("CASE\nCASE-1"));assertNull(rows(b).getFirst().get("executed_by"));}
    @Test void existingUpdateRetainsIdsCreationAndDefectLinksClearsOnlyChangedActors(){var f=fixture();var r=run(f);var rc=executions.listRunCases(f.actor(),f.project(),r.id()).getFirst();var st=executions.listRunSteps(f.actor(),f.project(),rc.id()).getFirst();executions.updateRunStep(f.actor(),f.project(),st.id(),new FunctionalTestExecutionService.RunStepInput("FAILED","本端结果"));executions.updateRunCase(f.actor(),f.project(),rc.id(),new FunctionalTestExecutionService.RunCaseInput("FAILED","本端备注"));defects.link(f.actor(),f.project(),f.defect().id(),new FunctionalDefectService.DefectLinkInput("RUN_CASE",rc.id()));var links=defects.links(f.actor(),f.project(),f.defect().id());var before=snapshot(f);var runBefore=executions.listRuns(f.actor(),f.project(),null).getFirst();apply(f,edit(value(f),d->d.put("title","历史新名称")));assertEquals(f.actor().userId(),rows(f).getFirst().get("executed_by"));assertEquals(f.actor().userId(),steps(f).getFirst().get("updated_by"));apply(f,edit(value(f),d->{result(d).put("note","跨端备注");step(result(d)).put("actualResult","跨端实际结果");}));assertNull(rows(f).getFirst().get("executed_by"));assertNull(steps(f).getFirst().get("updated_by"));assertEquals(before.layouts(),snapshot(f).layouts());assertEquals(links,defects.links(f.actor(),f.project(),f.defect().id()));assertEquals(runBefore.createdAt(),executions.listRuns(f.actor(),f.project(),null).getFirst().createdAt());}
    @Test void copiedHistoryRemainsEditableThroughOrdinaryExecutionApi(){var a=fixture();var b=fixture();run(a);apply(b,value(a));var rc=executions.listRunCases(b.actor(),b.project(),executions.listRuns(b.actor(),b.project(),null).getFirst().id()).getFirst();var st=executions.listRunSteps(b.actor(),b.project(),rc.id()).getFirst();executions.updateRunStep(b.actor(),b.project(),st.id(),new FunctionalTestExecutionService.RunStepInput("PASSED","真实结果"));executions.updateRunCase(b.actor(),b.project(),rc.id(),new FunctionalTestExecutionService.RunCaseInput("PASSED","网页备注"));assertEquals("COMPLETED",value(b).definition().get("status"));assertEquals("PASSED",result(value(b).definition()).get("status"));}
    @Test void layoutMismatchNeverReplacesCasesStepsOrDefectAssociations(){var f=fixture();run(f);var before=snapshot(f);assertThrows(ResponseStatusException.class,()->apply(f,edit(value(f),d->step(result(d)).put("text","另一历史结构"))));assertEquals(before,snapshot(f));assertThrows(ResponseStatusException.class,()->apply(f,edit(value(f),d->result(d).put("caseCode","CASE-OTHER"))));assertEquals(before,snapshot(f));}
    @Test void missingDependenciesRejectWholeBatchWithoutPartialCreation(){var a=fixture();var b=fixture();run(a);var good=value(a);var bad=edit(good,d->d.put("planCode","PLAN-MISSING"));bad=new Item("RUN","Z".repeat(26),bad.definition());var before=snapshot(b);Item finalBad=bad;assertThrows(ResponseStatusException.class,()->apply(b,good,finalBad));assertEquals(before,snapshot(b));}
    @Test void exactNoOpRetainsAllOrdinaryRowsAndMetadata(){var f=fixture();run(f);var before=snapshot(f);var rows=rows(f);var steps=steps(f);apply(f,value(f));assertEquals(before,snapshot(f));assertEquals(rows,rows(f));assertEquals(steps,steps(f));}
    @Test void durableReceiptReplaysCommittedLayoutAfterLaterEditAndRejectsReusedPayload(){var a=fixture();var b=fixture();run(a);var request=request(b,value(a));var receipt=sync.apply(b.actor(),b.project(),request);var rc=executions.listRunCases(b.actor(),b.project(),receipt.results().getFirst().itemId()).getFirst();executions.updateRunCase(b.actor(),b.project(),rc.id(),new FunctionalTestExecutionService.RunCaseInput("BLOCKED","后续编辑"));var after=snapshot(b);assertEquals(receipt,sync.apply(b.actor(),b.project(),request));assertEquals(after,snapshot(b));var altered=new Request(request.requestKey(),request.expectedUserId(),request.expectedRevision(),List.of(new Operation(request.operations().getFirst().operationId(),edit(value(a),d->d.put("title","changed")),request.operations().getFirst().createdAt())));assertThrows(ResponseStatusException.class,()->sync.apply(b.actor(),b.project(),altered));}
    @Test void auditFailureRollsBackAllRowsAndReceipt(){var a=fixture();var b=fixture();run(a);var before=snapshot(b);doThrow(new IllegalStateException("owned audit failure")).when(audit).record(any(),anyString(),anyString(),eq("FUNCTIONAL_HISTORY_SYNCED"),anyString(),anyString(),anyMap());try{assertThrows(IllegalStateException.class,()->apply(b,value(a)));assertEquals(before,snapshot(b));assertEquals(0,jdbc.sql("SELECT COUNT(*) FROM functional_history_sync_receipt WHERE project_id=:p").param("p",b.project()).query(Integer.class).single());}finally{reset(audit);}}
    @Test void invalidLifecyclePassedStepsTimePrecisionAndProtectedFieldsAreRejected(){var f=fixture();run(f);var v=value(f);for(java.util.function.Consumer<Map<String,Object>> change:List.<java.util.function.Consumer<Map<String,Object>>>of(d->d.put("createdBy",f.actor().userId()),d->d.put("status","COMPLETED"),d->d.put("startedAt","2026-10-10T10:00:00.1234Z"),d->d.put("startedAt","2040-01-01T00:00:00Z"),d->result(d).put("status","PASSED"),d->step(result(d)).put("number",0),d->result(d).put("executedBy",f.actor().userId()))){assertThrows(ResponseStatusException.class,()->apply(f,edit(v,change)));}assertEquals(v,value(f));}
    @Test void projectFileLinksAndDuplicateTargetsRejectBeforeWrites(){var f=fixture();run(f);var v=value(f);var before=snapshot(f);assertThrows(ResponseStatusException.class,()->apply(f,edit(v,d->result(d).put("note","/api/v1/projects/foreign/files/a/download"))));assertThrows(ResponseStatusException.class,()->apply(f,v,v));assertEquals(before,snapshot(f));}
    @Test void accessActorCsrfAndBodyLimitEnforced() throws Exception {var f=fixture();run(f);var other=fixture();access.upsertMember(f.actor(),f.project(),other.actor().getUsername(),"VIEWER");var url="/api/v1/projects/"+f.project()+"/functional/history/sync";mvc.perform(get(url).param("expectedUserId",other.actor().userId()).with(user(other.actor()))).andExpect(status().isForbidden());mvc.perform(get(url.replace(f.project(),other.project())).param("expectedUserId",f.actor().userId()).with(user(f.actor()))).andExpect(status().isForbidden());var body=json.writeValueAsBytes(request(f,value(f)));mvc.perform(post(url).with(user(f.actor())).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post(url).with(user(f.actor())).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk());assertThrows(ResponseStatusException.class,()->sync.snapshot(f.actor(),f.project(),other.actor().userId()));assertEquals(413,assertThrows(ResponseStatusException.class,()->sync.decode(new byte[FunctionalHistorySyncService.MAX_BYTES+1])).getStatusCode().value());assertThrows(ResponseStatusException.class,()->sync.decode((new String(body,java.nio.charset.StandardCharsets.UTF_8)+" {}").getBytes()));}
    @Test void ordinaryEditInvalidatesExpectedRevision(){var f=fixture();var r=run(f);var req=request(f,value(f));var rc=executions.listRunCases(f.actor(),f.project(),r.id()).getFirst();executions.updateRunCase(f.actor(),f.project(),rc.id(),new FunctionalTestExecutionService.RunCaseInput("FAILED","并发"));var after=snapshot(f);assertThrows(ResponseStatusException.class,()->sync.apply(f.actor(),f.project(),req));assertEquals(after,snapshot(f));}
    @Test void planDeletionAndHistorySyncShareProjectLock() throws Exception {var a=fixture();var b=fixture();run(a);var req=request(b,value(a));var tx=new TransactionTemplate(transactionManager);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);try(var pool=Executors.newFixedThreadPool(2)){var locked=new CountDownLatch(1);var release=new CountDownLatch(1);var first=pool.submit(()->tx.execute(s->{jdbc.sql("SELECT id FROM project WHERE id=:p FOR UPDATE").param("p",b.project()).query(String.class).single();locked.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}executions.deletePlan(b.actor(),b.project(),b.plan().id());return null;}));assertTrue(locked.await(10,TimeUnit.SECONDS));var second=pool.submit(()->sync.apply(b.actor(),b.project(),req));try{assertThrows(TimeoutException.class,()->second.get(200,TimeUnit.MILLISECONDS));}finally{release.countDown();}first.get(20,TimeUnit.SECONDS);assertInstanceOf(ResponseStatusException.class,assertThrows(ExecutionException.class,()->second.get(20,TimeUnit.SECONDS)).getCause());assertTrue(snapshot(b).items().isEmpty());}}
    @Test void projectHistoryCountIsBounded(){var f=fixture();for(int n=0;n<101;n++)run(f);assertThrows(ResponseStatusException.class,()->snapshot(f));}
    @Test void sourceClockAheadNeverBreaksOrdinaryEditingOrExistingHistoryTransfer(){var a=fixture();var b=fixture();run(a);var op=new Operation(UUID.randomUUID().toString(),value(a),java.time.Instant.parse("2027-10-12T10:00:00.120Z"));sync.apply(b.actor(),b.project(),new Request(UUID.randomUUID().toString(),b.actor().userId(),snapshot(b).revision(),List.of(op)));var copied=executions.listRuns(b.actor(),b.project(),null).getFirst();assertFalse(copied.updatedAt().isBefore(copied.createdAt()));var rc=executions.listRunCases(b.actor(),b.project(),copied.id()).getFirst();executions.updateRunCase(b.actor(),b.project(),rc.id(),new FunctionalTestExecutionService.RunCaseInput("FAILED","编辑跨时钟历史"));apply(b,edit(value(b),d->d.put("title","同步后继续编辑")));copied=executions.listRuns(b.actor(),b.project(),null).getFirst();assertFalse(copied.updatedAt().isBefore(copied.createdAt()));assertDoesNotThrow(()->transfer.export(b.actor(),b.project(),6,true,false,false,false,true));}

}
